def is_self_counting(A):
    """Checks if sequence A is a self-counting sequence."""
    L = len(A)

    # 1. Count occurrences of each value k in A
    counts = {}
    for k in range(L):
        counts[k] = 0

    for val in A:
        if 0 <= val < L:
            counts[val] += 1

    # 2. Check if the count of k matches a_k for all k
    for k in range(L):
        if counts[k] != A[k]:
            return False
    return True

# Test cases based on known solutions
tests = {
    4: [(1, 2, 1, 0)],
    7: [(3, 2, 1, 1, 0, 0, 0)],
    10: [(5, 2, 1, 1, 1, 0, 0, 0, 0, 0)]
}

results = {}

for L, sequences in tests.items():
    valid_solutions = []
    for seq_tuple in sequences:
        A = list(seq_tuple)
        if is_self_counting(A):
            valid_solutions.append(A)

    results[L] = valid_solutions

print("--- Verification Results ---")
for L, solutions in results.items():
    print(f"L={L}: Found {len(solutions)} solution(s).")
    for sol in solutions:
        print(f"  Solution: {sol}")

# Simple check for the sum of elements (must equal L)
for L, solutions in results.items():
    if solutions:
        A = solutions[0]
        sum_A = sum(A)
        print(f"  Check Sum for L={L}: Sum(A) = {sum_A}. Expected: {L}.")
